public static int findNthLeapYear(int Y, int N) {
    // Validate input: both Y and N must be positive
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Start year Y and position N must be positive integers.");
    }

    int count = 0;
    int year = Y;
    while (true) {
        if (isLeapYear(year)) {
            count++;
            if (count == N) {
                return year;
            }
        }
        year++;
        // Guard against potential integer overflow
        if (year < 0) {
            throw new ArithmeticException("Year value exceeded integer bounds while searching for the Nth leap year.");
        }
    }
}

/**
 * Checks whether the given year is a leap year according to the Gregorian calendar.
 *
 * @param year the year to check
 * @return true if the year is a leap year, false otherwise
 */
private static boolean isLeapYear(int year) {
    if (year % 4 != 0) {
        return false;
    }
    if (year % 100 != 0) {
        return true;
    }
    return year % 400 == 0;
